from collections import defaultdict

def find_components(grid):
    """Find connected components of 8s using BFS"""
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    def bfs(start):
        comp = [start]
        stack = [start]
        visited[start[0]][start[1]] = True
        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 8 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
                        comp.append((nr, nc))
        return comp

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and not visited[r][c]:
                comp = bfs((r,c))
                components.append(comp)

    return components

def color_map_from_demo(d_in, d_out, demo_name):
    """Get component-to-color mapping from a demo"""
    rows = len(d_in)
    cols = len(d_in[0])

    # Reset visited for new component finding
    visited = [[False]*cols for _ in range(rows)]
    component_id = 0

    mapping = {}

    for r in range(rows):
        for c in range(cols):
            if d_in[r][c] == 8 and not visited[r][c]:
                comp = [(r,c)]
                visited[r][c] = True
                stack = [(r,c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if d_in[nr][nc] == 8 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                                comp.append((nr, nc))

                # Find the color used for this component
                color_val = None
                for pos in comp:
                    color_val = d_out[pos[0]][pos[1]]
                    break

                mapping[f"comp_{component_id}"] = (color_val, sorted(comp))
                component_id += 1

    return mapping

