# Compute bounding boxes and check if cells map to quadrants

def bounding_box(grid):
    rows = len(grid)
    cols = len(grid[0])
    min_r, max_r = rows, -1
    min_c, max_c = cols, -1

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    return (min_r, max_r, min_c, max_c)

def quadrant_color(r, c, bbox):
    """Divide bounding box into quadrants and assign color based on position"""
    br, er, bc, ec = bbox
    # Normalize coordinates to [0, 1] within bounding box
    rel_r = r - br
    rel_c = c - bc
    size_r = er - br + 1
    size_c = ec - bc + 1

    norm_r = rel_r / size_r
    norm_c = rel_c / size_c

    if norm_r < 0.5 and norm_c < 0.5:
        return 1  # top-left
    elif norm_r >= 0.5 and norm_c >= 0.5:
        return 4  # bottom-right
    elif norm_r < 0.5 and norm_c >= 0.5:
        return 3  # top-right
    else:
        return 2  # bottom-left

