import math

def sector_color(r, c, bbox):
    """Assign color based on angle from center of bounding box"""
    br, er, bc, ec = bbox

    # Find center (use lower right 25% of shape as reference)
    cx = (bc + ec) / 2
    cy = (br + er) / 2

    dx = c - cx
    dy = r - cy

    # Avoid division by zero
    if abs(dx) < 0.01 and abs(dy) < 0.01:
        return 2

    angle = math.atan2(dy, dx) * 180 / math.pi  # degrees from -180 to 180

    # Map angle to sectors:
    # Right half (positive x): angles -90 to 90 -> colors 2-3
    # Left half (negative x): angles 90 to 270 (-90) -> colors 1-4

    if dx > 0:  # right side
        if -45 <= angle < 45:
            return 2  # direct right
        elif 45 <= angle < 135:
